INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT113-S3-Q17$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Purists want to ban nonaddictive drugs before competition because they are unnatural. The author answers that almost everything in sports is unnatural, from running shoes to gloves to machines, and none of it is banned for being unnatural. The author concludes that nonaddictive drugs should not be banned.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$The author rejects the purists' reason as "ridiculous" because being unnatural has never been grounds for a ban. So the author treats unnaturalness alone as not enough to justify banning something.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Being unnatural is not, by itself, a good enough reason to ban something.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT113-S3-Q17$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
